package dev.smokekitchen.test;

import dev.smokekitchen.content.*;
import dev.smokekitchen.world.*;
import net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.fabricmc.fabric.api.client.gametest.v1.world.TestWorldSave;
import net.minecraft.core.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.phys.*;

/** Raw crops -> actual drying -> finite jar filling/refilling -> real dose use/remainder/save. */
public final class SpiceChainFlowTest implements FabricClientGameTest {
    private static final BlockPos A=new BlockPos(2,100,0),B=new BlockPos(4,100,0),C=new BlockPos(6,100,0),MILL=new BlockPos(0,100,0),TABLE=new BlockPos(0,100,2),POT=new BlockPos(-2,100,0);
    private static void check(boolean value,String m){if(!value)throw new AssertionError(m);}
    private static KitchenBlockEntity be(net.minecraft.server.MinecraftServer s,BlockPos at){return (KitchenBlockEntity)s.overworld().getBlockEntity(at);}
    private static boolean observe(SurvivalPlayer p,java.util.function.Predicate<net.minecraft.server.MinecraftServer> test){boolean[] r={false};p.s.runOnServer(s->r[0]=test.test(s));return r[0];}
    private static void near(SurvivalPlayer p,BlockPos at){p.s.runCommand("tp @a "+(at.getX()+.5)+" 100 "+(at.getZ()-2.5));p.c.waitTicks(4);}
    private static void tap(SurvivalPlayer p,BlockPos at){near(p,at);p.click(at,Direction.UP);}
    private static void put(SurvivalPlayer p,String id,BlockPos at,int times){for(int i=0;i<times;i++){p.select("smoke_kitchen:"+id);tap(p,at);}}
    private static void cell(SurvivalPlayer p,BlockPos at,int slot){near(p,at);var v=new Vec3(at.getX()+(3+5*(slot%3))/16d,at.getY()+(slot<3?.3:.7),at.getZ()+7/16d);p.look(v);p.c.runOnClient(m->m.gameMode.useItemOn(m.player,InteractionHand.MAIN_HAND,new BlockHitResult(v,Direction.NORTH,at,false)));p.c.waitTicks(6);}
    private static void hang(SurvivalPlayer p,String id,BlockPos at,int slot){p.select("smoke_kitchen:"+id);cell(p,at,slot);}
    private static void takeAll(SurvivalPlayer p,BlockPos at){for(int i=0;i<27&&observe(p,s->!be(s,at).isEmpty());i++){p.emptyHand();p.c.getInput().holdKey(o->o.keyShift);tap(p,at);p.c.getInput().releaseKey(o->o.keyShift);}check(observe(p,s->be(s,at).isEmpty()),"Actual emptyhand retrieval clears the device");}
    private static void grind(SurvivalPlayer p){p.emptyHand();tap(p,MILL);}
    static void waitWorld(SurvivalPlayer p,int ticks,String phase){long[] start={0};p.s.runOnServer(s->start[0]=s.overworld().getGameTime());p.c.runOnClient(m->{FermentationFlowTest.fastClock=true;m.options.enableVsync().set(false);m.options.framerateLimit().set(260);m.options.pauseOnLostFocus=false;});p.s.runCommand("tick rate 200");try{for(int n=0;n<ticks+4000;n+=20){boolean[] done={false};p.s.runOnServer(s->{long elapsed=s.overworld().getGameTime()-start[0];done[0]=elapsed>=ticks;s.getPlayerList().getPlayers().forEach(x->x.sendOverlayMessage(Component.literal("自动验收："+phase+" "+Math.min(100,elapsed*100/ticks)+"% · 实际游戏刻")));});if(done[0])return;p.c.waitTicks(20);}throw new AssertionError("Actual drying clock stalled");}finally{p.s.runCommand("tick rate 20");p.c.runOnClient(m->FermentationFlowTest.fastClock=false);}}
    private static void photo(SurvivalPlayer p,String name,BlockPos at){p.emptyHand();p.s.runCommand("time set noon");p.s.runCommand("tp @a "+(at.getX()+2.5)+" 100 "+(at.getZ()-3.5));p.c.waitTicks(6);p.look(new Vec3(at.getX()+.5,at.getY()+.5,at.getZ()+.5));p.c.runOnClient(m->{m.options.fov().set(42);m.getToastManager().clear();});p.c.waitTicks(25);p.c.takeScreenshot("spices-"+name+"-0.1.22");p.c.runOnClient(m->m.options.fov().set(70));}
    private static int ownedUses(SurvivalPlayer p,String id){int[] r={-1};p.s.runOnServer(s->{for(var x:s.getPlayerList().getPlayers().getFirst().getInventory().getNonEquipmentItems())if(ResourceStates.baseId(x).equals(id))r[0]=SpiceMilling.remaining(x);});return r[0];}
    @Override public void runTest(ClientGameTestContext c){
        TestWorldSave save;
        try(var w=c.worldBuilder().create()){
            save=w.getWorldSave();var p=new SurvivalPlayer(c,w.getServer());p.s.runCommand("gamemode survival @a");p.s.runCommand("difficulty peaceful");p.s.runCommand("fill -6 98 -5 10 99 6 minecraft:smooth_stone");p.s.runCommand("weather clear 10000");p.s.runCommand("time set noon");
            for(String raw:new String[]{"minecraft:oak_log 8","minecraft:string 6","minecraft:cobblestone 6","minecraft:glass 3","minecraft:clay_ball 5","minecraft:book","minecraft:wheat_seeds","smoke_kitchen:black_pepper 6","smoke_kitchen:cumin 4","smoke_kitchen:sichuan_pepper","smoke_kitchen:chili 2","smoke_kitchen:shiitake"})p.s.runCommand("give @a "+raw);near(p,TABLE);
            if(net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded("iris"))c.runOnClient(m->{try{var a=Class.forName("net.irisshaders.iris.api.v0.IrisApi");check((Boolean)a.getMethod("isShaderPackInUse").invoke(a.getMethod("getInstance").invoke(null)),"Iris workflow requires actual active shader pack");}catch(ReflectiveOperationException e){throw new AssertionError(e);}});
            for(int i=0;i<8;i++)p.craft("oak_planks","oak_log");p.craft("crafting_table","oak_planks","oak_planks","oak_planks","oak_planks");p.closeMenu();p.select("crafting_table");tap(p,TABLE.below());p.emptyHand();tap(p,TABLE);for(int i=0;i<4;i++)p.craft("stick","oak_planks","","","oak_planks","","");p.craft("smoke_kitchen:hand_mill","","stick","","cobblestone","cobblestone","cobblestone","cobblestone","cobblestone","cobblestone");p.craft("smoke_kitchen:clay_pot","clay_ball","","clay_ball","clay_ball","","clay_ball","","clay_ball","");p.craft("smoke_kitchen:recipe_book","book","wheat_seeds");p.nextCraftScreenshot="spices-actual-empty-jars-recipe-0.1.22";p.craft("smoke_kitchen:empty_jar","glass","glass","glass","oak_planks");for(int i=0;i<3;i++)p.craft("smoke_kitchen:drying_rack","stick","","stick","oak_planks","string","oak_planks","stick","string","stick");p.closeMenu();
            for(var at:new BlockPos[]{A,B,C}){p.select("smoke_kitchen:drying_rack");tap(p,at.below());}p.select("smoke_kitchen:hand_mill");tap(p,MILL.below());p.select("smoke_kitchen:clay_pot");tap(p,POT.below());check(p.count("smoke_kitchen:empty_jar")==4,"Actual glass/plank recipe creates exactly4 jars");
            put(p,"black_pepper",MILL,1);grind(p);check(observe(p,s->be(s,MILL).items.getFirst().is(KitchenContent.item("black_pepper"))),"Fresh pepper cannot directly become dry powder");takeAll(p,MILL);
            for(int i=0;i<6;i++)hang(p,"black_pepper",A,i);for(int i=0;i<4;i++)hang(p,"cumin",B,i);hang(p,"sichuan_pepper",B,4);hang(p,"chili",B,5);hang(p,"shiitake",C,0);hang(p,"chili",C,1);waitWorld(p,600,"三种香料逐件干制");photo(p,"actual-half-spice-clusters",B);
            p.emptyHand();cell(p,C,0);put(p,"partially_dried_shiitake",MILL,1);put(p,"empty_jar",MILL,1);grind(p);check(observe(p,s->be(s,MILL).items.stream().anyMatch(x->x.is(KitchenContent.item("partially_dried_shiitake"))))&&p.count("smoke_kitchen:used_mushroom_powder")==0,"Half-dried ingredient and real jar remain unchanged");takeAll(p,MILL);hang(p,"partially_dried_shiitake",C,0);
            p.select("smoke_kitchen:recipe_book");c.runOnClient(m->m.gameMode.useItem(m.player,InteractionHand.MAIN_HAND));c.waitTicks(5);c.takeScreenshot("spices-actual-guide-0.1.22");p.closeMenu();
        }
        try(var w=save.open()){
            var p=new SurvivalPlayer(c,w.getServer());c.waitTicks(12);check(observe(p,s->DryingRack.progress(be(s,B).items.getFirst())>=600),"Actual world reopen keeps half-dried spice progress");waitWorld(p,2600,"香料实际晾干");check(observe(p,s->be(s,A).items.stream().limit(6).allMatch(x->x.is(KitchenContent.item("dried_black_pepper")))),"Actual black pepper dries into correct output");photo(p,"actual-dried-spice-clusters",B);for(var at:new BlockPos[]{A,B,C})for(int i=0;i<6;i++)if(observe(p,s->!be(s,at).isEmpty())){p.emptyHand();cell(p,at,i);}check(p.count("smoke_kitchen:dried_black_pepper")==6&&p.count("smoke_kitchen:dried_cumin")==4&&p.count("smoke_kitchen:dried_sichuan_pepper")==1,"All three actually dried crop identities and counts are retained");put(p,"dried_sichuan_pepper",POT,1);check(observe(p,s->be(s,POT).batch.count("sichuan_pepper")==1),"Actual dried Sichuan pepper can season a cooking vessel as its own ingredient");
            put(p,"dried_black_pepper",MILL,1);grind(p);check(observe(p,s->be(s,MILL).items.stream().anyMatch(x->x.is(KitchenContent.item("dried_black_pepper"))&&x.getCount()==1)),"No jar preserves real dry material");photo(p,"actual-no-jar-preserves-input",MILL);put(p,"empty_jar",MILL,1);grind(p);takeAll(p,MILL);check(ownedUses(p,"pepper_powder")==4&&p.count("smoke_kitchen:empty_jar")==3,"One dried pepper and exactly1 actual jar make4 doses, not16");
            put(p,"pepper_powder",MILL,1);put(p,"dried_black_pepper",MILL,3);grind(p);takeAll(p,MILL);check(p.count("smoke_kitchen:pepper_powder")==1&&ownedUses(p,"pepper_powder")==16&&p.count("smoke_kitchen:empty_jar")==3,"Three more actual dried peppers refill original jar to16 with no new jar");
            put(p,"pepper_powder",POT,3);check(ownedUses(p,"pepper_powder")==13,"Real seasoning actions leave13 uses");put(p,"pepper_powder",MILL,1);put(p,"dried_black_pepper",MILL,1);grind(p);check(observe(p,s->be(s,MILL).items.stream().anyMatch(x->ResourceStates.baseId(x).equals("pepper_powder")&&SpiceMilling.remaining(x)==13)&&be(s,MILL).items.stream().anyMatch(x->x.is(KitchenContent.item("dried_black_pepper")))),"Less than4 free doses preserves real jar and dry input");photo(p,"actual-too-full-preserves-input",MILL);takeAll(p,MILL);put(p,"pepper_powder",POT,1);put(p,"pepper_powder",MILL,1);put(p,"dried_black_pepper",MILL,1);grind(p);takeAll(p,MILL);check(ownedUses(p,"pepper_powder")==16,"Fourth real seasoning action makes room; one dried pepper exactly refills4");
            put(p,"dried_black_pepper",MILL,1);put(p,"dried_chili",MILL,1);put(p,"empty_jar",MILL,1);grind(p);check(observe(p,s->be(s,MILL).items.stream().filter(x->!x.isEmpty()).count()==3),"Mixed dry materials preserve both inputs and the actual jar");photo(p,"actual-mixed-spices-rejected",MILL);takeAll(p,MILL);
            for(String[] pair:new String[][]{{"dried_chili","chili_powder"},{"dried_cumin","cumin_powder"},{"dried_shiitake","mushroom_powder"}}){put(p,pair[0],MILL,1);put(p,"empty_jar",MILL,1);grind(p);takeAll(p,MILL);check(ownedUses(p,pair[1])==4,"Each actual dried ingredient makes only4 uses in its own real jar");}check(p.count("smoke_kitchen:empty_jar")==0,"All four owned jars are accounted for");photo(p,"actual-four-filled-types",MILL);
        }
        try(var w=save.open()){
            var p=new SurvivalPlayer(c,w.getServer());c.waitTicks(12);check(ownedUses(p,"pepper_powder")==16&&ownedUses(p,"cumin_powder")==4&&ownedUses(p,"chili_powder")==4&&ownedUses(p,"mushroom_powder")==4,"Actual reopening preserves full and partial jar quantities");for(String id:new String[]{"chili_powder","cumin_powder","mushroom_powder"})put(p,id,POT,4);check(p.count("smoke_kitchen:empty_jar")==3&&observe(p,s->be(s,POT).batch.spice==16),"Twelve actual seasoning uses return exactly3 empty jars, original4 pepper uses retained");photo(p,"actual-used-up-three-empty-jars",POT);
        }
        try(var w=save.open()){var p=new SurvivalPlayer(c,w.getServer());c.waitTicks(12);check(ownedUses(p,"pepper_powder")==16&&p.count("smoke_kitchen:empty_jar")==3&&observe(p,s->be(s,POT).batch.spice==16&&be(s,MILL).isEmpty()),"Third actual reopen retains finite contents/remainders and empty mill");photo(p,"final-actual-reopen",POT);}
    }
}
